export function generateScaffold(file, viablyAnalysis) {
  const { path, type, purpose } = file;
  const ext = path.split('.').pop();

  const header = `/**
 * ${purpose}
 * Feature: ${viablyAnalysis.feature_name}
 * Generated by Viably AI
 */\n\n`;

  if (ext === 'tsx') return generateTSXComponent(path, header, purpose);
  if (ext === 'ts' || ext === 'js') return generateTypeScriptFile(path, header, purpose);
  if (ext === 'py') return generatePythonFile(path, header, purpose);
  if (path.includes('test')) return generateTestFile(path, header, ext);

  return `${header}// TODO: Implement ${path}\n`;
}

function generateTSXComponent(path, header, purpose) {
  const componentName = getComponentName(path);
  return `${header}import React from 'react';

interface ${componentName}Props {
  // TODO: Define props
}

export const ${componentName}: React.FC<${componentName}Props> = (props) => {
  return (
    <div>
      <h1>${componentName}</h1>
      {/* TODO: Implement ${purpose} */}
    </div>
  );
};
`;
}

function generateTypeScriptFile(path, header, purpose) {
  const moduleName = getComponentName(path);
  return `${header}export class ${moduleName} {
  constructor() {
    // TODO: Initialize
  }

  // TODO: Implement ${purpose}
}

export default ${moduleName};
`;
}

function generatePythonFile(path, header, purpose) {
  const className = getClassName(path);
  return `${header}"""${purpose}"""

class ${className}:
    """${className} implementation"""

    def __init__(self):
        pass

    # TODO: Implement methods

if __name__ == "__main__":
    pass
`;
}

function generateTestFile(path, header, ext) {
  if (ext === 'tsx' || ext === 'ts') {
    return `${header}import { describe, it, expect } from 'vitest';

describe('Feature Test', () => {
  it('should work correctly', () => {
    expect(true).toBe(true);
  });
});
`;
  }

  if (ext === 'py') {
    return `${header}"""Test suite"""
import unittest

class TestFeature(unittest.TestCase):
    def test_basic(self):
        self.assertTrue(True)

if __name__ == '__main__':
    unittest.main()
`;
  }

  return `${header}// TODO: Implement tests\n`;
}

function getComponentName(path) {
  const filename = path.split('/').pop().split('.')[0];
  return filename.split(/[-_]/).map(word => word.charAt(0).toUpperCase() + word.slice(1)).join('');
}

function getClassName(path) {
  return getComponentName(path);
}
